    const renderLead=s=>`<div class="section-lead">${(s.leadLines||[s.lead]).map(x=>`<div>${rich(x)}</div>`).join('')}</div>`;
    function render(){const s=exam.sections[current],leadInBody=s.leadPlacement==='body',bodyLead=leadInBody&&s.lead?(s.leadLabel?`<div class="section-body-lead section-body-lead-labeled"><strong>${rich(s.leadLabel)}</strong><p>${rich(s.lead)}</p></div>`:`<div class="section-body-lead">${rich(s.lead)}</div>`):'';main.innerHTML=`<header class="section-heading ${leadInBody?'section-heading-with-body-lead':''}"><h2>${esc(s.number)}</h2>${leadInBody?'':renderLead(s)}<span class="points">${s.score}点</span></header>${bodyLead}${sectionBody(s)}`;[...nav.children].forEach((b,i)=>b.classList.toggle('active',i===current));document.getElementById('prevButton').disabled=current===0;document.getElementById('nextButton').disabled=exam.sections.length-1===current;document.getElementById('positionText').textContent=`${current+1} / ${exam.sections.length}`;bind();update();}
    function bind(){if(scored)return;main.querySelectorAll('.choice').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.key,n=Number(b.dataset.choice),type=b.dataset.type;if(type==='single-choice')responses[key]=Number(responses[key])===n?null:n;else{let values=(responses[key]||[]).map(Number);values=values.includes(n)?values.filter(x=>x!==n):values.length<answers.responses[key].answerNumbers.length?[...values,n]:values;responses[key]=values;}saveAndRender();}));main.querySelectorAll('select[data-order-key]').forEach(s=>s.addEventListener('change',()=>{const key=s.dataset.orderKey,index=Number(s.dataset.orderIndex),n=s.value?Number(s.value):null;let values=[...(responses[key]||[])];values.length=answers.responses[key].answerNumbers.length;if(n!=null)values=values.map((v,i)=>i!==index&&Number(v)===n?null:v);values[index]=n;responses[key]=values;saveAndRender();}));}
