    function go(i,shouldScroll=false){current=Math.max(0,Math.min(exam.sections.length-1,i));render();main.focus({preventScroll:true});if(shouldScroll)scrollTo({top:0,behavior:'smooth'});}
    function buildKey(){const entries=[];Object.values(answers.responses).forEach(d=>{if(d.type==='multi-select-unordered'){entries.push({n:d.answerNumbers[0],html:`<li class="answer-key-multiple"><span>${d.answerNumbers.join('～')}</span><strong>${d.correct.map(v=>circled[Number(v)-1]).join('・')}</strong><small>順不同</small></li>`});}else if(Array.isArray(d.correct)){d.answerNumbers.forEach((n,i)=>entries.push({n,html:`<li><span>${n}</span><strong>${circled[Number(d.correct[i])-1]}</strong></li>`}));}else{const n=d.answerNumbers[0];entries.push({n,html:`<li><span>${n}</span><strong>${circled[Number(d.correct)-1]}</strong></li>`});}});entries.sort((a,b)=>a.n-b.n);document.getElementById('answerKeyList').innerHTML=entries.map(x=>x.html).join('');}
    function sectionResultRows(){return exam.sections.map(section=>{const keys=new Set(section.questions.flatMap(question=>question.components?.map(component=>component.responseKey)||[question.responseKey])),units=(scored.units||[]).filter(unit=>(unit.responseKeys||[]).every(key=>keys.has(key))),maxScore=units.reduce((total,unit)=>total+Number(unit.points||0),0),score=units.reduce((total,unit)=>total+Number(unit.awardedPoints||0),0),slotNumbers=[...keys].flatMap(key=>answers.responses[key]?.answerNumbers||[]),correctSlots=slotNumbers.filter(number=>scored.slotOutcomes?.[String(number)]==='match').length;return{label:section.number,score,maxScore,correctSlots,slotCount:slotNumbers.length};});}
    const resultChoiceText=choice=>String(typeof choice==='string'?choice:Array.isArray(choice?.mappings)?choice.mappings.map(([label,value])=>`${label}: ${value}`).join(' / '):choice?.text||choice?.alt||'').replace(/<[^>]*>/g,'').replace(/\{\{[^|{}]+\|([^{}]+)\}\}/g,'$1');
    const resultAnswerHtml=(definition,value,choices=[])=>{const values=(Array.isArray(value)?value:[value]).filter(entry=>entry!=null&&entry!=='');if(!values.length)return'<span class="result-answer-empty">未回答</span>';return`<ol class="result-answer-list ${definition.type==='ordering'?'ordering-answer-list':''}">${values.map(entry=>{const number=Number(entry),text=resultChoiceText(choices[number-1]);return`<li><b>${esc(circled[number-1]||number)}</b>${text?`<span>${esc(text)}</span>`:''}</li>`;}).join('')}</ol>`;};
    const resultPrompt=q=>String(q.promptRich||q.prompt||'').replace(/\[\[(\d+)\]\]/g,'[$1]').replace(/\{\{[^|{}]+\|([^{}]+)\}\}/g,'$1').replace(/\s+/g,' ').trim();
    function questionResultGroups(){return exam.sections.map((section,sectionIndex)=>({label:section.number,sectionIndex,questions:section.questions.map(question=>{const components=question.components||[{responseKey:question.responseKey,choices:question.choices||[]}],keys=components.map(component=>component.responseKey),keySet=new Set(keys),units=(scored.units||[]).filter(unit=>(unit.responseKeys||[]).every(key=>keySet.has(key))),score=units.reduce((total,unit)=>total+Number(unit.awardedPoints||0),0),maxScore=units.reduce((total,unit)=>total+Number(unit.points||0),0),status=units.every(unit=>unit.status==='correct')?'correct':units.some(unit=>Number(unit.awardedPoints)>0)?'partial':'incorrect',answerNumbers=keys.flatMap(key=>answers.responses[key]?.answerNumbers||[]),answersHtml=components.map(component=>{const definition=answers.responses[component.responseKey],choices=component.choices||question.choices||[];return `<div><span>${definition.answerNumbers.length>1?`解答番号 ${definition.answerNumbers.join('・')}`:`解答番号 ${definition.answerNumbers[0]}`}</span><dl><dt>あなたの回答</dt><dd>${resultAnswerHtml(definition,responses[component.responseKey],choices)}</dd><dt>正答</dt><dd>${resultAnswerHtml(definition,definition.correct,choices)}</dd></dl></div>`;}).join('');return{label:question.number||`解答番号 ${answerNumbers.join('・')}`,questionId:question.questionId,prompt:resultPrompt(question),answerNumbers,score,maxScore,status,answersHtml};})}));}
    function renderQuestionResults(){const labels={correct:'正解',partial:'一部正解',incorrect:'不正解'};return `<section class="result-question-section"><div class="result-question-heading"><div><h3>設問別結果</h3><p>自分の回答と正答を比べ、復習する設問を確認できます。</p></div><button id="incorrectOnlyButton" type="button" aria-pressed="false">間違えた設問だけ表示</button></div>${questionResultGroups().map(section=>`<section class="result-question-group"><h4>${esc(section.label)}</h4><div class="result-question-list">${section.questions.map(question=>`<article class="result-question ${question.status}" data-result-status="${question.status}"><header><div><strong>${esc(question.label)}</strong><small>解答番号 ${question.answerNumbers.join('・')}</small></div><span class="result-status">${labels[question.status]}</span><b>${question.score} / ${question.maxScore} 点</b></header>${question.prompt?`<p class="result-question-prompt">${esc(question.prompt)}</p>`:''}<div class="result-answer-comparison">${question.answersHtml}</div><div class="result-question-actions"><button class="review-question-button" type="button" data-review-section="${section.sectionIndex}" data-review-target="${esc(question.questionId)}">この問題を確認</button></div></article>`).join('')}</div></section>`).join('')}</section>`;}
    function ensureReviewBar(){let bar=document.getElementById('reviewModeBar');if(bar)return bar;bar=document.createElement('aside');bar.id='reviewModeBar';bar.className='review-mode-bar';bar.hidden=true;bar.innerHTML='<span><strong>採点後の問題確認</strong>　回答は確定済みです。</span><button type="button">採点結果へ戻る</button>';nav.insertAdjacentElement('afterend',bar);bar.querySelector('button').addEventListener('click',returnToResultPage);return bar;}
