      if(session.index>=session.candidates.length){const previous=session.candidates.at(-1),pool=[...session.candidates];for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}if(pool.length>1&&pool[0].examId===previous.examId&&pool[0].questionId===previous.questionId)[pool[0],pool[1]]=[pool[1],pool[0]];session.candidates=pool;session.index=0;session.cycle=Number(session.cycle||1)+1;}
