    function scoreCurrentResponses(skipConfirmation=false,allowIncomplete=false,submissionReason='manual'){if(!allowIncomplete&&!scoring.isComplete(responses))return;if(!skipConfirmation&&!confirm('回答を提出して採点します。提出後は回答を変更できません。よろしいですか？'))return;preserveCurrentTiming();stopTimer();scored={...scoring.score(responses),submissionLocked:true,submissionReason,submittedAt:new Date().toISOString()};store.saveResult(scored);renderResultPage();addSubmissionNotice();}
    function abandonCurrentAttempt(){if(scored||requestedMode!=='practice')return;if(!confirm('試験を途中で終了し、その時点の回答を提出して採点します。未回答は得点にならず、提出後は回答を変更できません。よろしいですか？'))return;scoreCurrentResponses(true,true,'abandoned');}
